// Description: Helper class for Customer MDF Setup related operations
public class METCustomerMDFSetupHelper
{
}

Method.Source:
/// <summary>
/// New instance of METCustomerMDFSetupHelper
/// </summary>
private void new()
{
}

/// <summary>
/// Constructs and returns an instance of METCustomerMDFSetupHelper
/// </summary>
/// <returns>METCustomerMDFSetupHelper</returns>
internal static METCustomerMDFSetupHelper construct()
{
    return new METCustomerMDFSetupHelper();
}

/// <summary>
/// Gets the list of METCustomerMDFSetupTable records for a given customer, site, warehouse, and item
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "_siteId">InventSiteId</param>
/// <param name = "_warehouse">InventlocationId</param>
/// <param name = "_itemId">ItemId</param>
/// <returns>container</returns>
container getCustomerMDFSetupTableList(CustAccount _custAccount, InventSiteId _siteId, InventlocationId _warehouse, ItemId _itemId)
{ 
    container ret;

    METCustomerMDFTable customerMDFTable;
    METCustomerMDFSetupTable customerMDFSetupTable;

    while select customerMDFSetupTable
        exists join customerMDFTable
        where customerMDFSetupTable.RefRecId == customerMDFTable.recid
           && customerMDFTable.CustAccount == _custAccount
           && customerMDFTable.InventSiteId == _siteId
           && customerMDFTable.InventLocationId == _warehouse
    {
        if(this.isValidItemScope(customerMDFSetupTable,_itemId))
        {
            ret += [customerMDFSetupTable];
        }
    }

    return ret;
}

/// <summary>
/// Item is valid based on the item scope defined in the MDF setup record
/// </summary>
/// <param name = "_customerMdfSetupTable">METCustomerMDFSetupTable</param>
/// <param name = "_itemId">ItemId</param>
/// <returns>boolean</returns>
boolean isValidItemScope(METCustomerMDFSetupTable _customerMdfSetupTable, ItemId _itemId)
{
    boolean ret = true;
    switch(_customerMdfSetupTable.ItemScope)
    {
        case METItemScope::AllItems:
            ret = true;
            break;
        case METItemScope::ExplicitItemInclusion:
            ret = this.isItemIncluded(_customerMdfSetupTable, _itemId);
            break;
        case METItemScope::ItemsWithExclusions:
            ret = !this.isItemExcluded(_customerMdfSetupTable, _itemId);
            break;
    }
    return ret;
}

/// <summary>
/// Item is included in the inclusion list
/// </summary>
/// <param name = "_customerMdfSetupTable">MetCustomerMdfSetupTable</param>
/// <param name = "_itemId">ItemId</param>
/// <returns>boolean</returns>
boolean isItemIncluded(MetCustomerMdfSetupTable _customerMdfSetupTable, ItemId _itemId)
{
    METCustomerMDFItemInclusionTable customerMDFItemInclusionTable;
    EcoResProductCategory ecoResProductCategory;
    InventTable inventTable;

    select firstOnly RecId from customerMDFItemInclusionTable
        exists join ecoResProductCategory
        exists join inventTable
        where customerMDFItemInclusionTable.RefRecId == _customerMdfSetupTable.RecId
           && customerMDFItemInclusionTable.Category == ecoResProductCategory.Category
           && customerMDFItemInclusionTable.CategoryHierarchy == ecoResProductCategory.CategoryHierarchy
           && ecoResProductCategory.Product == inventTable.RecId
           && inventTable.ItemId == _itemId;

    return customerMDFItemInclusionTable.RecId;
}

/// <summary>
/// Item is excluded in the exclusion list
/// </summary>
/// <param name = "_customerMdfSetupTable">MetCustomerMdfSetupTable</param>
/// <param name = "_itemId">ItemId</param>
/// <returns>boolean</returns>
boolean isItemExcluded(MetCustomerMdfSetupTable _customerMdfSetupTable, ItemId _itemId)
{
    METCustomerMDFItemExclusionTable customerMDFItemExclusionTable;
    EcoResProductCategory ecoResProductCategory;
    InventTable inventTable;

    select firstOnly RecId from customerMDFItemExclusionTable
        exists join ecoResProductCategory
        exists join inventTable
        where customerMDFItemExclusionTable.RefRecId == _customerMdfSetupTable.RecId
           && customerMDFItemExclusionTable.Category == ecoResProductCategory.Category
           && customerMDFItemExclusionTable.CategoryHierarchy == ecoResProductCategory.CategoryHierarchy
           && ecoResProductCategory.Product == inventTable.RecId
           && inventTable.ItemId == _itemId;

    return customerMDFItemExclusionTable.RecId;
}
